export const initialState = Object.freeze({siteChoice:'exploring'});
export const learningContract = Object.freeze({
  driving_question:'What does a place in an interconnection queue actually establish?',
  fixed_boundary:'Dated ERCOT large-load and Dominion/PJM cases, connected to one grid-service decision.',
  changed_variable:'Project commitment, study maturity and permitted grid withdrawal.',
  primary_payoff:'Separate requested MW, forecasts, contracted capacity and actual demand before judging time to power.',
  closing_question:'What grid import, ramp, obligations and operating conditions can the project actually rely on?',
});
const s=(id,label,title,description,refs,extra={})=>({id,label,title,description,reference:'d03-interconnection-queues',sources:refs,...extra});
export const scenes = [
  s('queue-purpose','The race to connect','What does a place in the queue actually buy?', 'An additional case-study chapter after the recorded core course. ERCOT serves most of Texas; PJM coordinates a multi-state region in the eastern United States. This is a study of data-center grid access, not Internet networking. The dates refer to specific public snapshots, not a real-time queue dashboard.',[sources.ercot,sources.dominion]),
  s('two-queues','Two sides of the grid','Adding supply and connecting demand are different jobs.', 'Generator interconnection studies assess a new supply connection. Data centers seek utility service with applicable regional transmission/planning coordination. PJM’s New Services Queue also includes merchant transmission and long-term firm transmission-service requests; do not say that load can never enter it. The August 3, 2026 PJM announcement covers 715 generation projects and 201.5 GW nameplate accepted for study, not 201.5 GW of data centers or operational supply.',[sources.pjmLoad,sources.pjmSupply]),
  s('ercot-pipeline','ERCOT: read the stage','ERCOT’s headline is a pipeline of requests.', 'June 2026 snapshot, published July 29: 474.7 GW cumulative large-load pipeline through 2033. Selected categories shown on a common scale: 284.3 GW no studies submitted and 5.9 GW observed energized. The latter is all-time non-simultaneous peak consumption, not concurrent system load. Categories are selected, not a complete sum. The pipeline includes data centers and other large loads. Neither the gap nor the ratio is a cancellation rate.',[sources.ercot,sources.ercotDefinition]),
  s('site-options','One project, several requests','One campus can keep several sites in play.', 'Original teaching example: one 1 GW business deployment considers three mutually exclusive sites. Three 1 GW requests add to 3 GW, but the specified plan builds at most one campus. Choosing site B and withdrawing A/C reduces requests without cancelling the planned deployment. This is an incentive mechanism, not an estimate of duplicated ERCOT capacity. Relatively low early commitment can encourage options; SB6 requires disclosure of substantially similar requests.',[sources.sb6],{controls:[{key:'siteChoice',label:'Project stage',options:[['exploring','Explore three sites'],['selected','Choose B; withdraw A and C']]}],pedagogical_role:'prediction'}),
  s('ercot-analyst','SemiAnalysis: screen the requests','A queue total is not a buildout forecast.', 'Unmodified public SemiAnalysis figure from June 18, 2026. It compares April ERCOT requests (410 GW total, around 357 GW data centers) with its own 45.4 GW tracked data-center buildout through 2030 Q4. The phantom/duplicative classification belongs to the publisher’s model, not an ERCOT audit. Different horizons and tracking coverage mean the gap does not prove cancellation or fraud.',[sources.saRequests]),
  s('commitment-costs','Study fees and security','An inexpensive option becomes a financial commitment.', 'Texas rule 25.194 adopted September 18, effective October 8, 2026: $100,000 study fee and $50,000/MW security at the intermediate-agreement stage. A 1,000 MW request means $50 million face amount. Unused study funds are returned after the study; qualifying guarantees or letters of credit can satisfy security. At the subsequent large-load interconnection agreement, security is the greater of $50,000/MW or allocated system-upgrade costs. The proposed nonrefundable interconnection fee was removed. This is an adopted future-effective rule, not a claim that the entire new rule applies on September 20.',[sources.sb6,sources.security]),
  s('batch-zero','A study gate, not a switch','Eligible for Batch Zero does not mean ready to energize.', 'ERCOT’s July 28, 2026 preliminary eligibility snapshot gave approximately 205 GW eligible for Batch Zero. This is a different date and universe from the 474.7 GW June pipeline. A September 9 notice confirms verification requests continued through September. Documentation, applicable studies and approval to energize remain distinct steps; eligibility is not an operating permit. The sequence is conceptual and does not erase different base-load and studied-load routes.',[sources.batch,sources.verification]),
  s('dominion-contracts','PJM: the utility agreement','In Dominion’s territory, commitment builds in stages.', 'Dominion January 6, 2026 filing: engineering authorization follows site control and an engineered plan, with a $250,000 deposit and a typical 9–12-month study. ELOA is non-firm. CLOA authorizes construction and reserves capacity with cancellation obligations; ESA specifies electric service and collateral before the meter is set. These are Dominion processes, not universal PJM prices or guaranteed energization dates.',[sources.dominion]),
  s('dominion-demand','Agreements versus demand','Contracted capacity and actual demand tell different stories.', 'Dominion’s July 2025 agreements total 47 GW: 30.1 GW engineering authorizations, 7.1 GW construction authorizations and 9.8 GW electric service agreements. Its reported 2025 coincident data-center peak is 4 GW. Contract capacity, project stages and coincident demand differ; this is not an attrition funnel or a 4/47 project-success rate. Scope is Dominion Energy customers, not all PJM.',[sources.dominion]),
  s('forecast-filter','From requests to a forecast','Planners do not simply add every requested megawatt.', 'Original ERCOT 2025 forecast figure reproduced in the March 3, 2026 SemiAnalysis article. The 2030 total-system comparison is 208 GW submitted versus 138 GW adjusted. This is a historical forecast vintage, not the current queue or data-center-only demand. A forecast applies assumptions about timing and realization; it does not allocate service rights. Avoid treating the publisher’s broader market-policy argument as established causality.',[sources.saForecast]),
  s('staged-connection','Start within an import limit','A campus can grow while its grid import stays limited.', 'Simplified course redraw of ERCOT’s May 4, 2026 workshop illustration, reproduced by SemiAnalysis June 25: 1,000 MW requested load, 100 MW grid withdrawal and two 500 MW generators. With no local generation the power balance allows only 100 MW; with one generator 600 MW; with both, at most the 1,000 MW load, not 1,100 MW. Network, stability, fuel, permits and operating restrictions can further limit these amounts. This illustrates a staged proposal, not an approved project or automatic right. Loss of a generator cannot be assumed to transfer its entire load to the capped grid connection.',[sources.saStaged]),
  s('connection-terms','What can the campus rely on?','Get the service terms behind the megawatts.', 'Return to the opening question. A queue entry is evidence of a request. A usable project plan needs confirmed import and ramp, a credible date linked to the required work, allocation of construction/withdrawal obligations, and operating conditions such as curtailment or onsite-supply requirements. This is a synthesis of the two cases, not a universal tariff or a new speed ranking. Recorded Chapters 1–16 retain their own closing.',[sources.ercot,sources.dominion],{pedagogical_role:'synthesis'}),
];
